`default_nettype none

// 25 MHz ULX3S oscillator to a timing-closed 10 MHz LSC-1/UART domain.
// Parameters are generated by Project Trellis ecppll 1.4 for a 600 MHz VCO.
module ulx3s_core_pll (
    input  wire clk_25mhz,
    output wire clk_10mhz,
    output wire locked
);
    wire clkfb;
    (* FREQUENCY_PIN_CLKI="25" *)
    (* FREQUENCY_PIN_CLKOP="10" *)
    (* ICP_CURRENT="12", LPF_RESISTOR="8",
       MFG_ENABLE_FILTEROPAMP="1", MFG_GMCREF_SEL="2" *)
    EHXPLLL #(
        .PLLRST_ENA("DISABLED"), .INTFB_WAKE("DISABLED"),
        .STDBY_ENABLE("DISABLED"), .DPHASE_SOURCE("DISABLED"),
        .OUTDIVIDER_MUXA("DIVA"), .OUTDIVIDER_MUXB("DIVB"),
        .OUTDIVIDER_MUXC("DIVC"), .OUTDIVIDER_MUXD("DIVD"),
        .CLKI_DIV(5), .CLKOP_ENABLE("ENABLED"), .CLKOP_DIV(60),
        .CLKOP_CPHASE(30), .CLKOP_FPHASE(0),
        .FEEDBK_PATH("INT_OP"), .CLKFB_DIV(2)
    ) pll_i (
        .RST(1'b0), .STDBY(1'b0), .CLKI(clk_25mhz),
        .CLKOP(clk_10mhz), .CLKFB(clkfb), .CLKINTFB(clkfb),
        .PHASESEL0(1'b0), .PHASESEL1(1'b0), .PHASEDIR(1'b1),
        .PHASESTEP(1'b1), .PHASELOADREG(1'b1),
        .PLLWAKESYNC(1'b0), .ENCLKOP(1'b0), .LOCK(locked)
    );
endmodule

`default_nettype wire
